var t={en:`The MQTT broker stopped verifying registry identity, and a dashboard can actuate devices directly. The command audit path also disappeared.`,ua:`MQTT-брокер перестав перевіряти пристрої через реєстр, а панель напряму керує обладнанням. Шлях аудиту команд теж зник.`};var d={en:[`Remove dashboard→device direct control.`,`Restore registry→mqtt authentication and commands→audit.`,`Specify replay protection, expiry and device-side safety tests.`],ua:[`Прибери прямий dashboard→device.`,`Віднови registry→mqtt та commands→audit.`,`Визнач захист від повторів, строки дії й перевірки безпеки на пристрої.`]};var i=[{en:`Only verified command routes can reach devices.`,ua:`Лише перевірені команди доходять до пристроїв.`},{en:`Commands remain traceable in audit logs.`,ua:`Дії команд простежуються в аудиті.`}];var n={remove:[`registry->mqtt`,`commands->audit`],add:[{from:`dashboard`,to:`device`,kind:`sync`,label:`Intentional defect / Навмисна помилка`}]};var r={scenario:t,tasks:d,checks:i,mutations:n};export{i as checks,r as default,n as mutations,t as scenario,d as tasks};